'use strict';

function clamp(value, min, max) {
  if (![value, min, max].every(Number.isFinite) || min > max) throw new TypeError('invalid range');
  return Math.min(max, Math.max(min, value));
}

class QuotaPool {
  #capacity;
  #balance;

  constructor(capacity, initial = 0) {
    if (!Number.isFinite(capacity) || capacity <= 0 || !Number.isFinite(initial) || initial < 0 || initial > capacity) {
      throw new TypeError('invalid quota');
    }
    this.#capacity = capacity;
    this.#balance = initial;
  }

  get capacity() { return this.#capacity; }
  get balance() { return this.#balance; }
  get active() { return this.#balance > 0; }

  deposit(amount) {
    if (!Number.isFinite(amount) || amount <= 0) throw new TypeError('invalid amount');
    this.#balance = clamp(this.#balance + amount, 0, this.#capacity);
    return this.#balance;
  }

  spend(amount) {
    if (!Number.isFinite(amount) || amount <= 0) throw new TypeError('invalid amount');
    if (amount >= this.#balance) return false;
    this.#balance -= amount;
    return true;
  }

  ratio() {
    return this.#balance / this.#capacity;
  }
}

module.exports = { QuotaPool, clamp };

