'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['QuotaPool', 'clamp']);
const { QuotaPool, clamp } = api;

assert.strictEqual(clamp(5, 0, 10), 5);
assert.strictEqual(clamp(-1, 0, 10), 0);
assert.strictEqual(clamp(11, 0, 10), 10);
assert.strictEqual(clamp(2, 2, 2), 2);
for (const args of [[NaN, 0, 1], [0, Infinity, 1], [0, 0, -Infinity], [0, 2, 1], ['1', 0, 2]]) {
  assert.throws(() => clamp(...args));
}

const empty = new QuotaPool(10);
assert.strictEqual(empty.capacity, 10);
assert.strictEqual(empty.balance, 0);
assert.strictEqual(empty.active, false);
assert.strictEqual(empty.ratio(), 0);
assert.throws(() => { empty.capacity = 20; }, TypeError);
assert.throws(() => { empty.balance = 5; }, TypeError);
assert.throws(() => { empty.active = true; }, TypeError);
assert.strictEqual(empty.capacity, 10);
assert.strictEqual(empty.balance, 0);

const pool = new QuotaPool(10, 3);
assert.strictEqual(pool.active, true);
assert.strictEqual(pool.ratio(), 0.3);
assert.strictEqual(pool.deposit(4), 7);
assert.strictEqual(pool.deposit(100), 10);
assert.strictEqual(pool.balance, 10);
assert.strictEqual(pool.spend(11), false);
assert.strictEqual(pool.balance, 10);
assert.strictEqual(pool.spend(4), true);
assert.strictEqual(pool.balance, 6);
assert.strictEqual(pool.spend(6), true);
assert.strictEqual(pool.balance, 0);
assert.strictEqual(pool.active, false);

for (const amount of [0, -1, NaN, Infinity, '1']) {
  const balance = pool.balance;
  assert.throws(() => pool.deposit(amount));
  assert.strictEqual(pool.balance, balance);
  assert.throws(() => pool.spend(amount));
  assert.strictEqual(pool.balance, balance);
}
for (const args of [[0], [-1], [Infinity], [10, -1], [10, 11], [10, NaN], ['10', 0]]) {
  assert.throws(() => new QuotaPool(...args));
}
const full = new QuotaPool(5, 5);
assert.strictEqual(full.deposit(1), 5);
assert.strictEqual(full.ratio(), 1);

